window.SSH_PATH_PAGE={"page":"g12-mock-exam-3.html","grade":"12","bmod":{"1":["3–5","p.11, p.16"],"2":["6–8","p.10, p.30"],"3":["9–11","p.46"],"4":["12","p.60"],"5":["13–14","p.76"]},"set":"Full Mock Exam 3","term":1,"mods":"1–5","tests":{"1":{"items":{"m0":"VO_TOPIC","m1":"VO_TOPIC","m2":"VO_TOPIC","m3":"VO_TOPIC","m4":"GR_PRES","m5":"VO_TOPIC","m6":"VO_TOPIC","r0":"RD_MAIN","r1":"RD_DETAIL","r2":"RD_DETAIL","tf0":"RD_TFNG","tf1":"RD_TFNG","tf2":"RD_TFNG","a0":"VO_TOPIC","a1":"VO_TOPIC","a2":"VO_TOPIC","b0":"VO_PHR","b1":"VO_PREP","b2":"VO_PREP","vb0":"GR_FUT","vb1":"GR_PPERF","vb2":"GR_STAT","rep":"VO_WF","rw0":"GR_REPV","q12b":"RD_LIST","q12c":"RD_LIST"},"writing":["WR_COVER","WR_ADVDIS"],"mod":null}},"similar":{},"skills":{"GR_FUT":{"area":"Grammar","en":"Future forms (will, be going to, present for future, was going to)","ar":"صيغ المستقبل","obj":"Choose will (instant decisions, predictions), be going to (plans, evidence) and the present for timetables/arrangements.","rule_en":"will = decision at the moment of speaking, promises, predictions. be going to = a plan made before, or a prediction from evidence. Present continuous = fixed arrangements; present simple = timetables. was/were going to = a past plan that did not happen.","rule_ar":"will لقرار لحظي أو وعد أو توقع. be going to لخطة سابقة أو توقع له دليل. المضارع المستمر للترتيبات المؤكدة، والمضارع البسيط للجداول. و was/were going to لخطة في الماضي لم تتحقق.","ex":["\"There's no milk left!\" \"I'll buy some on my way home.\"","I was going to visit the zoo, but it rained."],"mis_en":"I go to buy some milk now. ✗ → I'll buy some milk. ✓ (instant decision)","mis_ar":"القرار اللحظي يكون بـ will.","frame":"I'll ___ (decision now). · I'm going to ___ (my plan).","simple_en":"Decide now → will. Plan → going to.","simple_ar":"قرار الآن ← will. خطة ← going to.","challenge":"Write a dialogue (6 lines) planning a school trip that uses four different future forms. Label why each one is used.","mi":{"mod":4,"lesson":null,"sb":null,"src":"mock-exam-2.html (Module 4 future forms)","bk":"23–24","bks":"Part 3 · Grammar 5 — Future forms","title":"Pack Your Bags"},"res":[{"k":"rule","en":"Review the Grammar Rule","ar":"راجع القاعدة","url":"my-revision-plan.html#skill=GR_FUT","lv":"all"},{"k":"practice","en":"Practice This Skill · Grade 12 Grammar Tests 1–3","ar":"تدرّب على المهارة · اختبارات القواعد","url":"g12-grammar.html","lv":"core"},{"k":"practice","en":"Practice This Skill · Module Test 4","ar":"تدرّب · اختبار الوحدة 4","url":"module-test-4.html","lv":"core"},{"k":"pdf","en":"Remedial & Enrichment Card · Future forms: will, going to, present continuous, present simple","ar":"بطاقة علاجية وإثرائية · صيغ المستقبل","url":"open.html?f=g12-card-m4-future-forms","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"23–24","sec":"Part 3 · Grammar 5 — Future forms","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"GR_PPERF":{"area":"Grammar","en":"Present perfect (simple and continuous) with for, since, yet, already, never … before","ar":"المضارع التام والتام المستمر مع for و since و yet","obj":"Use the present perfect for experiences and actions that connect the past to now, with for/since, yet, already, just, ever, never … before.","rule_en":"have/has + past participle connects the past to now. for + a period (for ten years); since + a starting point (since 2020). yet in questions/negatives, already and just in positives. have/has been + -ing stresses how long an activity has continued.","rule_ar":"have/has + التصريف الثالث يربط الماضي بالحاضر. for مع المدة (for ten years) و since مع نقطة البداية (since 2020). و yet في النفي والسؤال، و already و just في الإثبات. و have/has been + ing للتركيز على استمرار النشاط.","ex":["She has had this job for ten years.","I haven't used that app since 2023.","They have been working on the project for five years."],"mis_en":"I have visited Doha last year. ✗ → I visited Doha last year. ✓ (finished time → past simple)","mis_ar":"مع زمن منتهٍ مثل last year نستخدم الماضي البسيط وليس المضارع التام.","frame":"___ has/have ___ (past participle) for/since ___ .","simple_en":"for + time length; since + start time.","simple_ar":"for مع المدة، و since مع بداية الوقت.","challenge":"Rewrite three \"started … ago\" sentences using for and since, then write one sentence with the present perfect continuous and explain the difference.","mi":{"mod":2,"lesson":null,"sb":null,"src":"g12-module-tests.html (Module 2 tests) · mock-exam-2.html","bk":"17–18","bks":"Part 3 · Grammar 2 — Present perfect simple and continuous","title":"A Thirst for Knowledge"},"res":[{"k":"rule","en":"Review the Grammar Rule","ar":"راجع القاعدة","url":"my-revision-plan.html#skill=GR_PPERF","lv":"all"},{"k":"practice","en":"Practice This Skill · Grade 12 Grammar Tests 1–3","ar":"تدرّب على المهارة · اختبارات القواعد","url":"g12-grammar.html","lv":"core"},{"k":"practice","en":"Practice This Skill · Module 2 Test A","ar":"تدرّب · اختبار الوحدة 2 (أ)","url":"g12-module-tests.html?t=3","lv":"core"},{"k":"practice","en":"Irregular Verbs Trainer (past simple and past participle)","ar":"مدرب الأفعال الشاذة","url":"irregular-verbs.html","lv":"remedial"},{"k":"pdf","en":"Remedial & Enrichment Card · Present perfect simple and continuous","ar":"بطاقة علاجية وإثرائية · المضارع التام والمضارع التام المستمر","url":"open.html?f=g12-card-m2-present-perfect","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"17–18","sec":"Part 3 · Grammar 2 — Present perfect simple and continuous","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"GR_PRES":{"area":"Grammar","en":"Present simple and present continuous","ar":"المضارع البسيط والمضارع المستمر","obj":"Choose between the present simple (habits, facts) and the present continuous (now, temporary, annoying habits with always).","rule_en":"Present simple = facts, habits, timetables (every day, usually). Present continuous = am/is/are + -ing for actions happening now or around now (now, Look!, Listen!, at the moment). always + continuous = an annoying habit.","rule_ar":"المضارع البسيط للحقائق والعادات والجداول (every day, usually). والمضارع المستمر am/is/are + ing للأحداث التي تحدث الآن أو في هذه الفترة (now, Look!, Listen!). و always مع المستمر للتعبير عن عادة مزعجة.","ex":["Water boils at 100 °C.","Look! The children are playing in the garden.","My brother is always taking my charger!"],"mis_en":"Listen! Someone knocks on the door. ✗ → Listen! Someone is knocking on the door. ✓","mis_ar":"Listen! تدل على الآن، لذلك نستخدم المضارع المستمر وليس البسيط.","frame":"Look! ___ (subject) is/are ___ing … · Every day, ___ (subject) ___(s) …","simple_en":"Now → am/is/are + -ing. Every day → base verb (+s).","simple_ar":"الآن ← am/is/are + ing. كل يوم ← الفعل (+s).","challenge":"Write four sentences about your week: two routines and two things that are different this week. Explain why you chose each tense.","mi":{"mod":1,"lesson":null,"sb":null,"src":"g12-module-tests.html (Module 1 tests) · mock-exam-2.html","bk":"15–16","bks":"Part 3 · Grammar 1 — Present simple, present progressive, stative verbs","title":"Window on the World"},"res":[{"k":"rule","en":"Review the Grammar Rule","ar":"راجع القاعدة","url":"my-revision-plan.html#skill=GR_PRES","lv":"all"},{"k":"practice","en":"Practice This Skill · Grade 12 Grammar Tests 1–3","ar":"تدرّب على المهارة · اختبارات القواعد","url":"g12-grammar.html","lv":"core"},{"k":"practice","en":"Practice This Skill · Module 1 Test A","ar":"تدرّب · اختبار الوحدة 1 (أ)","url":"g12-module-tests.html?t=1","lv":"core"},{"k":"pdf","en":"Remedial & Enrichment Card · Present simple and present continuous","ar":"بطاقة علاجية وإثرائية · المضارع البسيط والمضارع المستمر","url":"open.html?f=g12-card-m1-present-tenses","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"15–16","sec":"Part 3 · Grammar 1 — Present simple, present progressive, stative verbs","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"GR_REPV":{"area":"Grammar","en":"Reporting verbs (offer, promise, advise, warn …)","ar":"أفعال النقل","obj":"Use reporting verbs with the correct pattern (+ to-infinitive, + object + to, + -ing, + that).","rule_en":"offer / promise / refuse / agree + to-infinitive. advise / warn / remind / tell + object + to-infinitive. suggest / admit / deny + -ing or that-clause. apologise for + -ing.","rule_ar":"offer و promise و refuse و agree + to + المصدر. و advise و warn و remind + مفعول + to + المصدر. و suggest و admit و deny + ing أو that. و apologise for + ing.","ex":["Khalid offered to help his brother with his science project.","Majid promised to call me as soon as he landed."],"mis_en":"He suggested to go to the beach. ✗ → He suggested going to the beach. ✓","mis_ar":"suggest يأتي بعده ing وليس to.","frame":"___ offered / promised to ___ . · ___ advised me to ___ .","simple_en":"offer / promise + to + verb.","simple_ar":"offer و promise + to + فعل.","challenge":"Turn a short conversation into a report using five different reporting verbs and their correct patterns.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"33–34","bks":"Part 3 · Grammar 10 — Reporting verbs"},"res":[{"k":"rule","en":"Review the Grammar Rule","ar":"راجع القاعدة","url":"my-revision-plan.html#skill=GR_REPV","lv":"all"},{"k":"practice","en":"Practice This Skill · Grade 12 Grammar Tests 1–3","ar":"تدرّب على المهارة · اختبارات القواعد","url":"g12-grammar.html","lv":"core"},{"k":"pdf","en":"Remedial & Enrichment Card · Reporting verbs","ar":"بطاقة علاجية وإثرائية · أفعال النقل","url":"open.html?f=g12-card-reporting-verbs","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"33–34","sec":"Part 3 · Grammar 10 — Reporting verbs","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"GR_STAT":{"area":"Grammar","en":"Stative verbs","ar":"أفعال الحالة","obj":"Recognise stative verbs (know, own, belong, smell, seem …) and avoid using them in continuous forms.","rule_en":"Stative verbs describe states, not actions: know, believe, own, belong, want, like, seem, smell, taste, weigh. Use them in simple forms, even when you mean \"now\".","rule_ar":"أفعال الحالة تصف حالة لا حدثًا، مثل know, own, belong, want, seem, smell. نستخدمها في الصيغة البسيطة حتى لو كان المعنى \"الآن\".","ex":["This perfume smells wonderful.","Faisal owns a small farm near Al Khor.","This bag belongs to Hamad."],"mis_en":"I am knowing the answer. ✗ → I know the answer. ✓","mis_ar":"know فعل حالة، فلا نقول am knowing.","frame":"___ (subject) know(s) / own(s) / belong(s) to ___ .","simple_en":"know, own, belong, want, seem → no -ing.","simple_ar":"أفعال مثل know و own و belong لا تأخذ ing.","challenge":"Some stative verbs can be dynamic (think, have, taste). Write two pairs of sentences that show the difference in meaning.","mi":{"mod":1,"lesson":null,"sb":null,"src":"g12-module-tests.html (Module 1 tests) · mock-exam-2.html","bk":"15–16","bks":"Part 3 · Grammar 1 — Present simple, present progressive, stative verbs","title":"Window on the World"},"res":[{"k":"rule","en":"Review the Grammar Rule","ar":"راجع القاعدة","url":"my-revision-plan.html#skill=GR_STAT","lv":"all"},{"k":"practice","en":"Practice This Skill · Grade 12 Grammar Tests 1–3","ar":"تدرّب على المهارة · اختبارات القواعد","url":"g12-grammar.html","lv":"core"},{"k":"practice","en":"Practice This Skill · Module 1 Test A","ar":"تدرّب · اختبار الوحدة 1 (أ)","url":"g12-module-tests.html?t=1","lv":"core"},{"k":"pdf","en":"Remedial & Enrichment Card · Stative verbs (and verbs with two meanings)","ar":"بطاقة علاجية وإثرائية · أفعال الحالة والأفعال ذات المعنيين","url":"open.html?f=g12-card-m1-stative-verbs","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"15–16","sec":"Part 3 · Grammar 1 — Present simple, present progressive, stative verbs","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"RD_DETAIL":{"area":"Reading","en":"Finding supporting details","ar":"تحديد التفاصيل الداعمة","obj":"Locate the sentence in the text that answers a specific question.","rule_en":"Underline the key words in the question, scan the text for them or their synonyms, then read that sentence carefully. Your answer must come from the text, not from your opinion.","rule_ar":"ضع خطًا تحت الكلمات المفتاحية في السؤال، وابحث عنها أو عن مرادفاتها في النص، ثم اقرأ الجملة التي تحتوي على الدليل بعناية. يجب أن تأتي الإجابة من النص لا من رأيك.","ex":[],"mis_en":"Answering from general knowledge instead of the text.","mis_ar":"الإجابة من المعلومات العامة بدل النص.","frame":"According to paragraph ___, ___ because the text says \"___\".","simple_en":"Find the key word → find the sentence → copy the idea.","simple_ar":"الكلمة المفتاحية ← الجملة ← الفكرة.","challenge":"Write two detail questions about a new paragraph for a classmate, with the line numbers of the answers.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"35","bks":"Part 4 · Reading — how to answer every official question"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=RD_DETAIL","lv":"all"},{"k":"pdf","en":"Remedial & Enrichment Card · Reading skills for the official exam","ar":"بطاقة علاجية وإثرائية · مهارات القراءة لأسئلة الاختبار","url":"open.html?f=g12-card-reading-skills","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"35","sec":"Part 4 · Reading — how to answer every official question","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"RD_LIST":{"area":"Reading","en":"Finding TWO / THREE points (mention / give)","ar":"استخراج نقطتين أو ثلاث نقاط","obj":"Find and list several separate points from one paragraph.","rule_en":"Go to the paragraph named in the question. Look for lists: commas, and, also, another, such as. Each point must be different; write short phrases, one point per line.","rule_ar":"اذهب إلى الفقرة المحددة في السؤال، وابحث عن القوائم (الفواصل و and و also و such as). يجب أن تكون كل نقطة مختلفة، واكتب عبارات قصيرة، نقطة في كل سطر.","ex":[],"mis_en":"Writing the same idea twice in different words.","mis_ar":"كتابة الفكرة نفسها مرتين بكلمات مختلفة.","frame":"1) ___ 2) ___ 3) ___ (from paragraph ___).","simple_en":"One idea per line. Use the text words.","simple_ar":"فكرة واحدة في كل سطر، وبكلمات النص.","challenge":"Highlight every list in a reading text in a different colour and turn one list into a short summary sentence.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"35","bks":"Part 4 · Reading — how to answer every official question"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=RD_LIST","lv":"all"},{"k":"pdf","en":"Remedial & Enrichment Card · Reading skills for the official exam","ar":"بطاقة علاجية وإثرائية · مهارات القراءة لأسئلة الاختبار","url":"open.html?f=g12-card-reading-skills","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"35","sec":"Part 4 · Reading — how to answer every official question","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"RD_MAIN":{"area":"Reading","en":"Main idea and writer's purpose","ar":"الفكرة الرئيسة وهدف الكاتب","obj":"Identify what a whole text (or paragraph) is mainly about and why it was written.","rule_en":"Read the title, the first and last paragraphs and the first sentence of each paragraph. The right answer covers the WHOLE text, not one detail. Wrong options are often true details that are too narrow.","rule_ar":"اقرأ العنوان والفقرة الأولى والأخيرة والجملة الأولى من كل فقرة. الإجابة الصحيحة تشمل النص كله وليس تفصيلًا واحدًا، والخيارات الخاطئة غالبًا تفاصيل صحيحة لكنها ضيقة.","ex":[],"mis_en":"Choosing a true detail from one paragraph instead of the main idea.","mis_ar":"اختيار تفصيل صحيح من فقرة واحدة بدل الفكرة العامة.","frame":"This text is mainly about ___ because paragraphs 1–5 all talk about ___ .","simple_en":"Ask: what is the WHOLE text about?","simple_ar":"اسأل نفسك: عمّ يتحدث النص كله؟","challenge":"Write a one-sentence summary for each paragraph, then a one-sentence summary of the whole text.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"35","bks":"Part 4 · Reading — how to answer every official question"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=RD_MAIN","lv":"all"},{"k":"pdf","en":"Remedial & Enrichment Card · Reading skills for the official exam","ar":"بطاقة علاجية وإثرائية · مهارات القراءة لأسئلة الاختبار","url":"open.html?f=g12-card-reading-skills","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"35","sec":"Part 4 · Reading — how to answer every official question","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"RD_TFNG":{"area":"Reading","en":"True / False / Not Mentioned (Not Given)","ar":"صح / خطأ / غير مذكور","obj":"Decide whether a statement agrees with, contradicts or is not in the text.","rule_en":"True = the text says the same thing. False = the text says the opposite. Not Mentioned / Not Given = the text does not give this information. Watch for small words: only, all, first, every.","rule_ar":"صح: النص يقول المعنى نفسه. خطأ: النص يقول عكسه. غير مذكور: النص لا يذكر المعلومة. انتبه للكلمات الصغيرة مثل only و all و first.","ex":[],"mis_en":"Choosing False when the text simply does not say it (it is Not Mentioned).","mis_ar":"اختيار \"خطأ\" بينما النص لا يذكر المعلومة أصلًا (غير مذكور).","frame":"The text says ___, so the statement is T / F / NM.","simple_en":"Same → T. Opposite → F. Not there → NM.","simple_ar":"نفس المعنى ← صح. عكسه ← خطأ. غير موجود ← غير مذكور.","challenge":"Write three T/F/NM statements of your own about a text (one of each) and swap with a partner.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"35","bks":"Part 4 · Reading — how to answer every official question"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=RD_TFNG","lv":"all"},{"k":"pdf","en":"Remedial & Enrichment Card · Reading skills for the official exam","ar":"بطاقة علاجية وإثرائية · مهارات القراءة لأسئلة الاختبار","url":"open.html?f=g12-card-reading-skills","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"35","sec":"Part 4 · Reading — how to answer every official question","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"VO_PHR":{"area":"Vocabulary","en":"Phrasal verbs","ar":"الأفعال المركبة","obj":"Understand and use common phrasal verbs from the module (check in/out, drop off, call off, take off …).","rule_en":"A phrasal verb = verb + particle with a new meaning: check out (leave a hotel), drop someone off (take by car and leave), call off (cancel), take off (leave the ground).","rule_ar":"الفعل المركب = فعل + أداة بمعنى جديد: check out (مغادرة الفندق) و drop off (توصيل شخص) و call off (إلغاء) و take off (إقلاع).","ex":["My father dropped me off at school before he went to work.","All events were called off because of the storm."],"mis_en":"The plane took up at 9. ✗ → The plane took off at 9. ✓","mis_ar":"الإقلاع = take off.","frame":"I ___ (phrasal verb) ___ when ___ .","simple_en":"Learn phrasal verbs with a picture or example.","simple_ar":"احفظ الفعل المركب مع صورة أو مثال.","challenge":"Write a short travel story using six phrasal verbs from the module.","mi":{"mod":4,"lesson":"Vocabulary 4B – Travel phrasal verbs","sb":"p.60","src":"mock-exam-2.html (Vocabulary 4B) · Revision Booklet","bk":"12","bks":"Part 2 · Module 4 — Travel and travel phrasal verbs (4B)","title":"Pack Your Bags"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=VO_PHR","lv":"all"},{"k":"practice","en":"Practice This Skill · Module Test 4","ar":"تدرّب · اختبار الوحدة 4","url":"module-test-4.html","lv":"core"},{"k":"practice","en":"Practice This Skill · Grade 12 Vocabulary Tests 1–3","ar":"تدرّب · اختبارات المفردات","url":"g12-vocabulary.html","lv":"core"},{"k":"practice","en":"Grade 12 Vocabulary Cards (with Arabic)","ar":"بطاقات المفردات بالعربية","url":"vocab-cards.html","lv":"remedial"},{"k":"pdf","en":"Remedial & Enrichment Card · Travel phrasal verbs and travel vocabulary","ar":"بطاقة علاجية وإثرائية · الأفعال المركبة ومفردات السفر","url":"open.html?f=g12-card-m4-travel-phrasal-verbs","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"12","sec":"Part 2 · Module 4 — Travel and travel phrasal verbs (4B)","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"VO_PREP":{"area":"Vocabulary","en":"Dependent prepositions (verb / adjective + preposition)","ar":"حروف الجر الملازمة","obj":"Use the preposition that goes with a verb or adjective (benefit from, capable of, concentrate on …).","rule_en":"Some verbs and adjectives always take the same preposition: benefit from, capable of, concentrate on, pay attention to, feed on, a threat to, typical of. Learn them as one chunk.","rule_ar":"بعض الأفعال والصفات تأتي دائمًا مع حرف جر معيّن مثل benefit from و capable of و concentrate on و pay attention to. احفظها كوحدة واحدة.","ex":["Students can benefit from joining clubs at school.","Our team is capable of winning the competition."],"mis_en":"Please concentrate in your studies. ✗ → Please concentrate on your studies. ✓","mis_ar":"concentrate يأتي مع on.","frame":"___ (verb/adjective) + ___ (preposition) + ___ .","simple_en":"Learn verb + preposition together: benefit from.","simple_ar":"احفظ الفعل مع حرف الجر معًا.","challenge":"Make flashcards for 12 verb/adjective + preposition pairs and test a partner.","mi":{"mod":2,"lesson":"Vocabulary 2B – Verb + preposition","sb":"p.30","src":"mock-exam-2.html (Vocabulary 2B, SB p.30)","bk":"8","bks":"Part 2 · Module 2 — Dependent prepositions","title":"A Thirst for Knowledge"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=VO_PREP","lv":"all"},{"k":"practice","en":"Practice This Skill · Module 2 Test A","ar":"تدرّب · اختبار الوحدة 2 (أ)","url":"g12-module-tests.html?t=3","lv":"core"},{"k":"practice","en":"Practice This Skill · Grade 12 Vocabulary Tests 1–3","ar":"تدرّب · اختبارات المفردات","url":"g12-vocabulary.html","lv":"core"},{"k":"practice","en":"Grade 12 Vocabulary Cards (with Arabic)","ar":"بطاقات المفردات بالعربية","url":"vocab-cards.html","lv":"remedial"},{"k":"pdf","en":"Remedial & Enrichment Card · Dependent prepositions","ar":"بطاقة علاجية وإثرائية · حروف الجر الملازمة","url":"open.html?f=g12-card-m2-prepositions","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"8","sec":"Part 2 · Module 2 — Dependent prepositions","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"VO_TOPIC":{"area":"Vocabulary","en":"Topic vocabulary in context","ar":"مفردات الوحدة في السياق","obj":"Choose the word that fits the meaning and the collocation of the sentence.","rule_en":"Read the whole sentence, decide the part of speech the gap needs, then use the clues around it (topic, collocation, positive/negative meaning). Learn new words in phrases, not alone.","rule_ar":"اقرأ الجملة كاملة، وحدد نوع الكلمة المطلوبة، ثم استخدم القرائن حولها (الموضوع، والمتلازمات، والمعنى الإيجابي أو السلبي). احفظ الكلمات في عبارات لا منفردة.","ex":["Many immigrants who arrived in Qatar decades ago have built successful businesses."],"mis_en":"Choosing a word that looks familiar but does not fit the meaning.","mis_ar":"اختيار كلمة مألوفة لا تناسب المعنى.","frame":"The word ___ means ___ . Example: ___ .","simple_en":"Learn the word with its example and Arabic meaning.","simple_ar":"احفظ الكلمة مع مثالها ومعناها بالعربية.","challenge":"Make a mind map of ten module words with collocations, then write a short paragraph using six of them.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"3–14","bks":"Part 2 · Vocabulary — Modules 1–5"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=VO_TOPIC","lv":"all"},{"k":"practice","en":"Practice This Skill · Grade 12 Vocabulary Tests 1–3","ar":"تدرّب · اختبارات المفردات","url":"g12-vocabulary.html","lv":"core"},{"k":"practice","en":"Grade 12 Vocabulary Cards (with Arabic)","ar":"بطاقات المفردات بالعربية","url":"vocab-cards.html","lv":"remedial"},{"k":"pdf","en":"Remedial & Enrichment Card · Confusing words: people, customs and originals","ar":"بطاقة علاجية وإثرائية · كلمات متشابهة: الأشخاص والعادات والأصالة","url":"open.html?f=g12-card-m1-vocabulary","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Remedial & Enrichment Card · Charity and giving: words and word families","ar":"بطاقة علاجية وإثرائية · مفردات العمل الخيري واشتقاقاتها","url":"open.html?f=g12-card-m3-charity-vocabulary","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"3–14","sec":"Part 2 · Vocabulary — Modules 1–5","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"VO_WF":{"area":"Vocabulary","en":"Word formation (suffixes and word families)","ar":"تكوين الكلمات (اللواحق)","obj":"Form nouns, adjectives, verbs and adverbs with the right suffix.","rule_en":"Look at the gap: after a/an/the or an adjective → noun (-tion, -ment, -ness, -ity, -ance). Before a noun or after be → adjective (-ful, -ive, -able, -al, -ous, -ing/-ed). After a verb → adverb (-ly). Check if it needs to be plural or negative (un-, dis-).","rule_ar":"انظر إلى الفراغ: بعد a/the أو صفة ← اسم (tion, ment, ness, ity). قبل اسم أو بعد be ← صفة (ful, ive, able, al, ous). بعد فعل ← ظرف (ly). وتحقق هل يحتاج إلى جمع أو نفي (un, dis).","ex":["The exploration of the Sahara was dangerous in the past.","Our science teacher showed us a very informative film."],"mis_en":"The develop of plastic-eating bacteria is promising. ✗ → The development … ✓","mis_ar":"بعد The نحتاج إلى اسم: development.","frame":"the + ___ (noun: -tion / -ment / -ness) · a very ___ (adjective: -ful / -ive / -able)","simple_en":"After the → noun. Before a noun → adjective.","simple_ar":"بعد the ← اسم. قبل اسم ← صفة.","challenge":"Build word-family tables (verb · noun · adjective · adverb) for eight module words and write one sentence for each form.","mi":{"mod":2,"lesson":"Vocabulary 2B – Word formation","sb":"p.30–31","src":"mock-exam-2.html (Word Formation, SB p.30–31)","bk":"6–7","bks":"Part 2 · Module 2 — Word formation: suffixes","title":"A Thirst for Knowledge"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=VO_WF","lv":"all"},{"k":"practice","en":"Practice This Skill · Module 2 Test A","ar":"تدرّب · اختبار الوحدة 2 (أ)","url":"g12-module-tests.html?t=3","lv":"core"},{"k":"practice","en":"Practice This Skill · Grade 12 Vocabulary Tests 1–3","ar":"تدرّب · اختبارات المفردات","url":"g12-vocabulary.html","lv":"core"},{"k":"practice","en":"Grade 12 Vocabulary Cards (with Arabic)","ar":"بطاقات المفردات بالعربية","url":"vocab-cards.html","lv":"remedial"},{"k":"pdf","en":"Remedial & Enrichment Card · Word formation: building adjectives","ar":"بطاقة علاجية وإثرائية · تكوين الكلمات: اشتقاق الصفات","url":"open.html?f=g12-card-m1-word-formation","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Remedial & Enrichment Card · Word formation: nouns with -ion, -ation, -ment, -ance","ar":"بطاقة علاجية وإثرائية · تكوين الأسماء: tion و ation و ment و ance","url":"open.html?f=g12-card-m2-noun-suffixes","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Open PDF Worksheet · Grade 12 · Complete Revision Booklet","ar":"افتح ورقة العمل · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"6–7","sec":"Part 2 · Module 2 — Word formation: suffixes","lv":"core"},{"k":"pdf","en":"Exam practice · Grade 12 · Advanced Practice Tests (PDF)","ar":"تدريب على الاختبار · الاختبارات المتقدمة","url":"open.html?f=g12-advanced-practice-tests-pdf","page":null,"lv":"enrichment"}]},"WR_ADVDIS":{"area":"Writing","en":"Advantages and disadvantages essay","ar":"مقال المزايا والعيوب","obj":"Discuss advantages and disadvantages with examples and a balanced conclusion.","rule_en":"Introduction → advantages with examples (Firstly, Moreover) → disadvantages with examples (However, On the other hand) → conclusion and your opinion.","rule_ar":"مقدمة ← المزايا مع أمثلة (Firstly, Moreover) ← العيوب مع أمثلة (However, On the other hand) ← خاتمة ورأيك.","ex":[],"mis_en":"Listing points without examples or justification.","mis_ar":"سرد النقاط دون أمثلة أو تبرير.","frame":"One advantage of ___ is ___ . For example, ___ . However, ___ . In conclusion, ___ .","simple_en":"Advantages, disadvantages, conclusion.","simple_ar":"مزايا، عيوب، خاتمة.","challenge":"Rank your advantages and disadvantages by importance and justify the order in your conclusion.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"38","bks":"Part 5 · Writing B — The advantages-and-disadvantages essay"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=WR_ADVDIS","lv":"all"},{"k":"lesson","en":"Open the writing lesson · Grade 12 Writing Scaffold · Advantages & Disadvantages Essay","ar":"افتح درس الكتابة · دعم الكتابة · مقال المزايا والعيوب","url":"g12-scaffold-advantages-disadvantages.html","lv":"core"},{"k":"practice","en":"Writing Coach (check your draft)","ar":"مدرب الكتابة (راجع مسودتك)","url":"writing-coach.html","lv":"all"},{"k":"pdf","en":"Remedial & Enrichment Card · Advantages and disadvantages essay","ar":"بطاقة علاجية وإثرائية · مقال المزايا والعيوب","url":"open.html?f=g12-card-writing-advantages-disadvantages","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Model answer and plan · Grade 12 · Complete Revision Booklet","ar":"نموذج الإجابة والخطة · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"38","sec":"Part 5 · Writing B — The advantages-and-disadvantages essay","lv":"core"}]},"WR_COVER":{"area":"Writing","en":"Cover letter (job application)","ar":"خطاب التقديم لوظيفة","obj":"Write a formal cover letter that matches your qualities to the job advert.","rule_en":"Dear Mr/Ms … → the job and where you saw it → qualifications → experience → skills and personal qualities → why they should hire you / available for interview → Yours sincerely.","rule_ar":"Dear Mr/Ms ← الوظيفة وأين رأيت الإعلان ← المؤهلات ← الخبرة ← المهارات والصفات ← لماذا يختارونك وموعد المقابلة ← Yours sincerely.","ex":[],"mis_en":"Not linking your skills to the requirements in the advert.","mis_ar":"عدم ربط مهاراتك بمتطلبات الإعلان.","frame":"I am writing to apply for the position of ___ , which I saw on ___ . I have ___ . I believe I am suitable because ___ .","simple_en":"Job, qualifications, experience, why me.","simple_ar":"الوظيفة، المؤهلات، الخبرة، لماذا أنا.","challenge":"Underline every requirement in the advert and write one sentence proving each one.","mi":{"mod":null,"lesson":null,"sb":null,"src":null,"bk":"36–37","bks":"Part 5 · Writing A — The cover letter (job application)"},"res":[{"k":"rule","en":"Review the skill","ar":"راجع المهارة","url":"my-revision-plan.html#skill=WR_COVER","lv":"all"},{"k":"lesson","en":"Open the writing lesson · Grade 12 Writing Scaffold · Cover Letter","ar":"افتح درس الكتابة · دعم الكتابة · خطاب التقديم","url":"g12-scaffold-job-application.html","lv":"core"},{"k":"practice","en":"Writing Coach (check your draft)","ar":"مدرب الكتابة (راجع مسودتك)","url":"writing-coach.html","lv":"all"},{"k":"pdf","en":"Remedial & Enrichment Card · Cover letter (job application)","ar":"بطاقة علاجية وإثرائية · خطاب التقديم لوظيفة","url":"open.html?f=g12-card-writing-cover-letter","page":"1–2","sec":"Revision card + remedial (p.1) · enrichment + key (p.2)","lv":"remedial"},{"k":"pdf","en":"Model answer and plan · Grade 12 · Complete Revision Booklet","ar":"نموذج الإجابة والخطة · ملزمة المراجعة الشاملة · الصف الثاني عشر","url":"open.html?f=g12-complete-revision-booklet-pdf","page":"36–37","sec":"Part 5 · Writing A — The cover letter (job application)","lv":"core"}]}}};
